let strs = find_strings("libliapp.so");
for st in strs {
  report("LIAPP Identifier", st.address, "HIGH", st.value);
}
let is_liapp = strs.len() > 0;
if is_liapp {
  let inits = find_symbols("init_array_");
  for ini in inits {
    report("LIAPP Loader Entry (" + ini.name + ")", ini.address, "HIGH", "Constructor in .init_array (unpacks DEX & starts checks)");
  }
  let apis = ["inotify_rm_watch", "dl_iterate_phdr", "fork", "prctl"];
  for api in apis {
    let syms = find_symbols(api);
    for s in syms {
      if s.name == api && s.address > 0 {
        let xrefs = get_xrefs(s.address);
        if xrefs.len() == 0 {
          report("LIAPP Import: " + api, s.address, "MEDIUM", "PLT stub (called indirectly or via wrapper)");
        }
        for x in xrefs {
          report("LIAPP Calls " + api, x.from, "HIGH", x.instruction);
          if x.kind == "Jump" && x.from > 64 {
            let win = disasm(x.from - 64, 64);
            let wrap_start = -1;
            let idx = 0;
            while idx + 1 < win.len() {
              let ins = win[idx];
              let nxt = win[idx + 1];
              let is_end = ins.mnemonic == "b" || ins.mnemonic == "jmp" || (ins.mnemonic == "bx" && ins.op_str == "lr") || (ins.mnemonic == "ret" && !nxt.op_str.contains("x30") && !nxt.op_str.contains("lr"));
              if is_end {
                wrap_start = nxt.address;
              }
              idx += 1;
            }
            if wrap_start > 0 {
              let callers = get_xrefs(wrap_start);
              for c in callers {
                report("LIAPP Decision Site (" + api + ")", c.from, "HIGH", "Calls wrapper " + hex(wrap_start) + " -> " + c.instruction);
              }
            }
          }
        }
      }
    }
  }
}
